internalNotes.description:
- Default value: 
```
  if (record.field('type').equals('release')) {
    let query = sys.data.createQuery('dev.tasks')
      .field('project').equals(record.field('project').id())
      .field('status').equals('completed')
      .field('type').notEquals('release')
      .sortBy('releaseInformation.number', 'desc');
    let lastRelease = sys.data.find(query);
    let listing = '<ul>';
    while (lastRelease.hasNext()) {
      let task = lastRelease.next();
      if (!task.field('releaseNotes.internalNotes').isEmpty()) {
        listing += '<li><strong>'+ task.label() +'</strong>' +  ': ' + task.field('releaseNotes.internalNotes').val() + '</li>';
      }
    } 
    listing += '</ul>';
    if (!listing.includes("<li>")) {
      listing = null
    }
    return listing;
  } else {
    return record.field('releaseNotes.internalNotes').val();
  }
```
